'use strict';
let managerFilter={};
const imURL='/api/ingestion/';
const imBrandOptions=()=>enums.brands.map(b=>`<option value="${esc(b.brand_id)}">${esc(b.name)} · ${esc(b.brand_id)}</option>`).join('');
const imNotice=()=>'<p class="lab-notice">Shared Supabase registry · acquired evidence import. Live FSQ download, paid AI execution, and generic menu acquisition are not connected. Accepted canonical records are shared. Remote reset is refused.</p>';
const imBind=(id,fn)=>{const f=document.getElementById(id);if(f)f.onsubmit=async e=>{e.preventDefault();const button=f.querySelector('button');button.disabled=true;try{await fn(Object.fromEntries(new FormData(f)));}catch(error){toast(error.message);}finally{button.disabled=false;}};};
async function managerPage(){
 const [d,runs]=await Promise.all([api(imURL+'jobs?'+new URLSearchParams(managerFilter)),api('/api/runs')]);
 const admin=user.role==='ADMIN';
 shell('Ingestion',`<div class="heading"><div><h1>Ingestion Manager</h1><p>Register acquisitions, resolve identity blocks and continue saved work.</p></div><button id="im-refresh">Refresh</button></div>${imNotice()}<p class="muted">Worker: ${esc(d.worker?.state||'Unknown')} · ${esc(d.worker?.error||'Checkpoint worker available while the server is running')}</p>
 <div class="cards">${Object.entries(d.counts).map(([state,n])=>`<div class="card"><span class="muted">${esc(nice(state))}</span><strong>${n}</strong></div>`).join('')||'<p>No manager jobs registered.</p>'}</div>
 <form id="im-filter" class="filters"><label>Status<select name="state">${opts(['QUEUED','RUNNING','PAUSED','BLOCKED_BY_BURP','COMPLETED','COMPLETED_WITH_ISSUES','FAILED','CANCELED'],managerFilter.state,'All')}</select></label><label>Search<input name="q" value="${esc(managerFilter.q||'')}" placeholder="Job, Brand or Business ID"></label><button>Filter</button></form>
 <p>${d.total} matching jobs · <button id="im-prev" ${d.offset===0?'disabled':''}>Previous</button> <button id="im-next" ${d.offset+d.limit>=d.total?'disabled':''}>Next</button></p><section class="panel flush"><table><thead><tr><th>Job</th><th>State</th><th>Progress</th><th>Last update</th></tr></thead><tbody>${d.items.map(j=>`<tr><td><a href="#ingestion/${esc(j.id)}">${esc(j.label)}</a><br>${esc(nice(j.kind))}</td><td>${badge(j.state)}</td><td>${j.processed} / ${j.total} processed · ${j.blocked} blocked</td><td>${esc(dateLabel(j.updated_at))}<br>${esc(j.error||'')}</td></tr>`).join('')||'<tr><td colspan="4">No matching jobs.</td></tr>'}</tbody></table></section>
 ${admin?`<section class="panel"><h2>Start targeted ingestion</h2><p>Import acquired restaurant evidence. Missing identity will create a linked review case before Business creation.</p><form id="im-create" class="account-form">
 <label class="stack">Operation<select name="kind"><option value="BUSINESS">Specific Business</option><option value="NEW_BRAND">New Brand</option><option value="BRAND_EXPANSION">Expand existing Brand</option><option value="RECOVERY">Recover acquired records</option></select></label>
 <label class="stack">Existing Brand (optional)<select name="brand_id"><option value="">Identity needs review / new Brand</option>${imBrandOptions()}</select></label>
 <label class="stack">Provider<select name="provider"><option>FIRST_PARTY</option><option>FSQ</option><option>OWNER_SUBMISSION</option><option>USER_REPORT</option></select></label>
 <label class="stack">Restaurant / job name<input name="name" maxlength="200"></label>
 <label class="stack">Source or FSQ Place ID<input name="id" maxlength="200"></label>
 <label class="stack">Street address<input name="street"></label><label class="stack">Suite / terminal<input name="street2"></label>
 <label class="stack">City<input name="city"></label><label class="stack">State<input name="state" maxlength="2"></label><label class="stack">Postal code<input name="postcode"></label>
 <label class="stack">Official evidence URL<input name="url" type="url" placeholder="https://official.example/location"></label>
 <label class="stack">Acquired evidence / identity support<textarea name="evidence_text"></textarea></label>
 <details><summary>Batch import / scheduling / spending limit</summary><label class="stack">Normalized acquired records (optional JSON array, up to 100)<textarea name="records" placeholder="Leave blank to use the fields above"></textarea></label>
 <label class="stack">Schedule (optional ISO timestamp with timezone)<input name="scheduled_at" placeholder="2026-11-01T09:00:00-07:00"></label>
 <label class="stack">Maximum processing expense, USD<input name="budget" type="number" value="0" min="0" max="100" step="0.01"></label></details>
 <button class="primary">Review and start job</button></form></section>
 <section class="panel"><h2>FSQ update inbox</h2><p>Upload authorized source changes. This inbox does not download provider datasets.</p><form id="im-release"><label class="stack">Release / partition ID<input name="release_id" required></label><label class="stack">Changes (JSON array)<textarea name="events" required placeholder='[{"action":"add","record":{"id":"fsq-id","name":"Restaurant","street":"10 Main St","city":"Denver","state":"CO","postcode":"80202"}}]'></textarea></label><button>Stage source update</button></form>
 ${d.releases.map(r=>`<p><a href="#source-release/${encodeURIComponent(r.id)}">${esc(r.id)}</a> · ${esc(r.state)} ${r.job_id?`<a href="#ingestion/${esc(r.job_id)}">View job</a>`:`<button data-process-release="${esc(r.id)}">Process staged update</button>`}</p>`).join('')||'<p>No source updates staged.</p>'}</section>
 <section class="panel"><h2>Recurring inbox processing</h2><p>The scheduler checks staged source releases through scheduled PostgreSQL checkpoints. Empty coverage prevents new automatic acquisition. Known Business changes still enter review.</p>
 <form id="im-settings"><label class="stack">Enabled<select name="enabled"><option value="0">Off</option><option value="1" ${d.settings.enabled?'selected':''}>On</option></select></label>
 <label class="stack">Interval in seconds<input name="interval_seconds" type="number" min="30" value="${d.settings.interval_seconds}"></label>
 <label class="stack">Coverage states, separated by commas<input name="coverage_states" value="${esc(JSON.parse(d.settings.coverage_states).join(','))}" placeholder="CO,CT"></label>
 <label class="stack">Maximum candidates per update<input name="max_candidates" type="number" min="1" max="100" value="${d.settings.max_candidates}"></label>
 <label class="stack">Automatically queue eligible new candidates<select name="auto_acquire"><option value="0">Off</option><option value="1" ${d.settings.auto_acquire?'selected':''}>On — unresolved identity remains blocked</option></select></label>
 <label class="stack">Reviewed closure automation policy<select name="closure_automation"><option value="0">Off</option><option value="1" ${d.settings.closure_automation?'selected':''}>Allow explicit independent official evidence reviewed by administrator</option></select></label>
 <label class="stack">Maximum USD per automated job<input name="budget" type="number" min="0" max="100" step="0.01" value="${d.settings.budget_microusd/1000000}"></label><button>Save processing policy</button></form>
 <p>Last check: ${esc(dateLabel(d.settings.last_check))} · Next check: ${esc(dateLabel(d.settings.next_check))}</p></section>
 <section class="panel"><h2>Approved first-party Brand rules</h2><p>Rules require an exact official hostname and acquired supporting text. Names and FSQ chain hints do not authorize Brand association.</p><form id="im-rule"><label class="stack">Brand<select name="brand_id" required>${imBrandOptions()}</select></label><label class="stack">Official hostname<input name="host" required placeholder="locations.example.com"></label><label class="stack">Verification reason<textarea name="reason" required></textarea></label><button>Approve host rule</button></form>${d.brand_rules.map(r=>`<p>${esc(r.host)} → ${esc(r.brand_id)} · ${esc(r.reason)}</p>`).join('')}</section>`:''}
 <details class="panel"><summary>Existing ingestion history (${runs.items.length})</summary>${runTable(runs.items)}</details>`);
 document.getElementById('im-refresh').onclick=managerPage;
 document.getElementById('im-prev').onclick=()=>{managerFilter.offset=Math.max(0,d.offset-d.limit);managerPage();};
 document.getElementById('im-next').onclick=()=>{managerFilter.offset=d.offset+d.limit;managerPage();};
 imBind('im-filter',async b=>{managerFilter=b;await managerPage();});
 imBind('im-create',async b=>{
  const budget=Math.round(Number(b.budget)*1000000);
  if(!window.confirm(`Start ${nice(b.kind)} using imported evidence? Maximum API/AI authorization: $${(budget/1000000).toFixed(2)}. Identity may require review.`))return;
  const records=b.records.trim()?JSON.parse(b.records):[{id:b.id,name:b.name,street:b.street,street2:b.street2||null,city:b.city,state:b.state.toUpperCase(),postcode:b.postcode,source:{url:b.url||undefined,type:b.provider==='FIRST_PARTY'?'FIRST_PARTY':b.provider,evidence_text:b.evidence_text,observed_at:new Date().toISOString()}}];
  const d=await api(imURL+'jobs',{operation_id:crypto.randomUUID(),kind:b.kind,label:b.name,provider:b.provider,brand_id:b.brand_id||null,records,scheduled_at:b.scheduled_at||null,budget_microusd:budget,confirm_budget:true});location.hash='ingestion/'+d.id;
 });
 imBind('im-release',async b=>{await api(imURL+'releases',{release_id:b.release_id,events:JSON.parse(b.events)});await managerPage();});
 imBind('im-settings',async b=>{const budget=Math.round(Number(b.budget)*1000000);if(!confirm('Apply this automation policy with a maximum of $'+(budget/1000000).toFixed(2)+' per job?'))return;await api(imURL+'settings',{enabled:Number(b.enabled),interval_seconds:Number(b.interval_seconds),max_candidates:Number(b.max_candidates),auto_acquire:Number(b.auto_acquire),closure_automation:Number(b.closure_automation),coverage_states:b.coverage_states.split(',').map(x=>x.trim().toUpperCase()).filter(Boolean),budget_microusd:budget,confirm_budget:true});await managerPage();});
 imBind('im-rule',async b=>{await api(imURL+'settings',{action:'brand_rule',...b});await managerPage();});
 document.querySelectorAll('[data-process-release]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api(imURL+'process-release',{release_id:button.dataset.processRelease});await managerPage();}catch(error){toast(error.message);button.disabled=false;}});
}

async function managerDetail(id){
 const d=await api(imURL+'jobs/'+encodeURIComponent(id));const admin=user.role==='ADMIN';
 // Refresh Brand choices after an identity decision establishes a new Brand.
 enums=await api('/api/enums');
 const counts=d.candidates.reduce((a,c)=>(a[c.outcome||c.state]=(a[c.outcome||c.state]||0)+1,a),{});
 shell('Ingestion',`<a href="#Ingestion">← Ingestion Manager</a><div class="heading"><div><h1>${esc(d.label)}</h1><p>${badge(d.state)} · ${esc(nice(d.kind))} · ${esc(d.id)}</p></div><button id="im-detail-refresh">Refresh</button></div>${imNotice()}
 <div class="cards">${Object.entries(counts).map(([k,v])=>`<div class="card"><span class="muted">${esc(nice(k))}</span><strong>${v}</strong></div>`).join('')}</div>
 <section class="panel"><h2>Job controls</h2><p>${esc(d.error||'No job-level error.')}</p><p>Maximum authorized expense: $${(d.budget_microusd/1000000).toFixed(2)} · ${d.usage.length} usage reservations. Menu Items: not acquired; no reuse or creation count is claimed.</p>${admin?['pause','resume','retry','cancel'].map(action=>`<button data-im-action="${action}" ${action==='pause'?!['QUEUED','RUNNING','BLOCKED_BY_BURP','FAILED'].includes(d.state)?'disabled':'':action==='cancel'?['COMPLETED','COMPLETED_WITH_ISSUES','CANCELED'].includes(d.state)?'disabled':'':!['PAUSED','FAILED','BLOCKED_BY_BURP'].includes(d.state)?'disabled':''}>${action==='resume'?'Resume Ingestion':nice(action)}</button>`).join(' '):'<p>Administrator access is required for ingestion actions.</p>'}</section>
 ${d.candidates.map(c=>`<section class="panel"><h2>${esc(c.payload.name)} · ${badge(c.state)}</h2><p>${esc([c.payload.street,c.payload.street2,c.payload.city,c.payload.state].filter(Boolean).join(', '))}</p><p>Source: ${esc(c.provider)} · ${esc(c.external_id)}<br>Checkpoint: ${esc(c.checkpoint)} · Attempts: ${c.attempts}<br>Business: ${esc(c.business_id||'Not established')} · Brand: ${esc(c.brand_id||'Unresolved')}</p><p>${esc(c.error||c.outcome||'Awaiting processing')}</p>
 ${c.cases.map(link=>`<p>${badge(link.priority)} <a href="#case/${esc(link.case_id)}">${esc(link.issue_summary)}</a> · ${esc(nice(link.status))}<br>${esc(link.required_decision)}</p>`).join('')}
 ${c.decision?'<p>Identity approved. Use Resume Ingestion when the affected candidates are ready.</p>':''}
 ${admin&&['BLOCKED','FAILED'].includes(c.state)?`<form data-identity="${esc(c.id)}"><h3>Approve identity / split this candidate</h3><label class="stack">Existing Brand<select name="brand_id"><option value="">Establish a distinct new Brand</option>${imBrandOptions()}</select></label><label class="stack">New distinct Brand name (if selected)<input name="new_brand_name" value="${esc(c.payload.name)}"></label><label class="stack">Existing Business ID (only when identity evidence establishes the same Business)<input name="business_id"></label><label class="stack">Acquisition correction (optional complete normalized JSON record)<textarea name="corrected_record"></textarea></label><label class="stack">Identity evidence / decision reason<textarea name="reason" required></textarea></label><button>Approve identity; keep ingestion paused</button></form>`:''}
 <details><summary>Acquired evidence / saved decision</summary><pre>${esc(pretty(c.payload))}</pre><pre>${esc(c.decision||'No authorized identity decision')}</pre></details></section>`).join('')}
 ${d.lifecycle.map(l=>`<section class="panel"><h2>Closure investigation · ${esc(l.decision)}</h2><p>${esc(l.business_id)} · <a href="#case/${esc(l.case_id)}">Verification case</a></p><p>FSQ signals alone cannot change operational status. Preserve identity, Items and history.</p>${admin?`<form data-closure="${esc(l.id)}" data-business="${esc(l.business_id)}"><label class="stack">Action<select name="action"><option value="approve">Approve independently corroborated permanent closure</option><option value="automate">Apply enabled reviewed automation policy</option><option value="reverse">Reverse this applied closure decision</option></select></label><label class="stack">Independent evidence type<select name="kind"><option>OFFICIAL_CLOSURE_ANNOUNCEMENT</option><option>CORPORATE_EXPLICIT_CLOSURE</option></select></label><label class="stack">Official closure announcement URL<input name="url" type="url"></label><label class="stack">Explicit closure statement<textarea name="quote"></textarea></label><label><input name="independent" type="checkbox"> I inspected independent official evidence, rather than a republication of the FSQ signal</label><br><label><input name="no_contradiction" type="checkbox"> No unresolved material contradiction with stronger evidence</label><label class="stack">Decision / reversal justification<textarea name="reason" required></textarea></label><button>Record authorized lifecycle decision</button></form>`:''}</section>`).join('')}
 <section class="panel"><h2>Usage and expense</h2><pre>${esc(pretty(d.usage))}</pre>${admin?`<form id="im-budget"><label class="stack">New maximum authorized USD<input name="budget" type="number" min="0" max="100" step="0.01" value="${d.budget_microusd/1000000}"></label><label class="stack">Spending authorization reason<textarea name="reason" required></textarea></label><button>Review spending authorization</button></form>`:''}</section>
 <section class="panel"><h2>Operational audit</h2>${d.audit.map(a=>`<div class="audit-entry"><strong>${esc(nice(a.action))}</strong> · ${esc(a.actor_id||'System')} · ${esc(dateLabel(a.at))}<pre>${esc(a.detail)}</pre></div>`).join('')}</section>`);
 document.getElementById('im-detail-refresh').onclick=()=>managerDetail(id);
 imBind('im-budget',async b=>{const budget=Math.round(Number(b.budget)*1000000);if(!confirm('Authorize up to $'+(budget/1000000).toFixed(2)+' for this job?'))return;await api(imURL+'control',{job_id:id,version:d.version,action:'budget',budget_microusd:budget,confirm_budget:true,reason:b.reason});await managerDetail(id);});
 document.querySelectorAll('[data-im-action]').forEach(button=>button.onclick=async()=>{if(button.dataset.imAction==='cancel'&&!confirm('Cancel remaining work? Already created records and evidence will be retained.'))return;button.disabled=true;try{await api(imURL+'control',{job_id:id,version:d.version,action:button.dataset.imAction});await managerDetail(id);}catch(error){toast(error.message);await managerDetail(id);}});
 document.querySelectorAll('[data-identity]').forEach((f,index)=>{f.id='im-identity-'+index;imBind(f.id,async b=>{await api(imURL+'identity',{job_id:id,version:d.version,candidate_id:f.dataset.identity,brand_id:b.brand_id||null,new_brand_name:b.new_brand_name,business_id:b.business_id||null,reason:b.reason,...(b.corrected_record.trim()?{corrected_record:JSON.parse(b.corrected_record)}:{})});await managerDetail(id);});});
 document.querySelectorAll('[data-closure]').forEach((f,index)=>{f.id='im-closure-'+index;imBind(f.id,async b=>{if(!confirm('Apply this lifecycle decision to the shared Business status? Identity and historical relationships will be retained.'))return;await api(imURL+'lifecycle',{id:f.dataset.closure,business_version:d.business_versions[f.dataset.business],action:b.action,reason:b.reason,corroboration:{kind:b.kind,url:b.url,quote:b.quote,observed_at:new Date().toISOString(),independent:b.independent==='on',contradiction:b.no_contradiction!=='on'}});await managerDetail(id);});});
}

async function managerRelease(id){
 const d=await api(imURL+'release?'+new URLSearchParams({id}));
 shell('Ingestion',`<a href="#Ingestion">← Ingestion Manager</a><h1>Source update · ${esc(d.id)}</h1><p>${badge(d.state)} · ${esc(dateLabel(d.created_at))}</p>${imNotice()}${d.job_id?`<p><a href="#ingestion/${esc(d.job_id)}">Inspect resulting ingestion job</a></p>`:''}<section class="panel"><h2>Source changes and processing decisions</h2>${d.events.map(e=>`<article class="audit-entry"><strong>${esc(e.action)} · ${esc(e.external_id)}</strong><p>${esc(nice(e.disposition||'Awaiting processing'))}<br>Existing Business: ${esc(e.business_id||'Unmapped')}</p><details><summary>Acquired change evidence</summary><pre>${esc(pretty(e.payload))}</pre></details></article>`).join('')}</section><section class="panel"><h2>Release audit</h2>${d.audit.map(a=>`<p>${esc(nice(a.action))} · ${esc(dateLabel(a.at))}<br>${esc(a.detail)}</p>`).join('')}</section>`);
}

/* Campaign coordination uses the existing hosted BURP Auth, receipts and checkpoints. */
const ingestionV01Page=managerPage;
const ingestionV01Route=route;
const iv2='/api/ingestion/v02/';
const ivMoney=v=>v==null?'Unavailable':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:4}).format(v/1000000);
const ivCards=rows=>'<div class="cards">'+rows.map(([label,value])=>`<div class="card"><span class="muted">${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('')+'</div>';
const ivNav=()=>'<a href="#Ingestion">Ingestion</a> · <a href="#ingestion-queue/import/FSQ_UPDATE">Process FSQ Update</a> · <a href="#ingestion-v02/brands">Brand readiness</a> · <a href="#ingestion-v02/advanced">Advanced</a>';
const ivBrandOptions=selected=>enums.brands.map(b=>`<option value="${esc(b.brand_id)}" ${selected===b.brand_id?'selected':''}>${esc(b.name)} · ${esc(b.brand_id)}</option>`).join('');
const ivStrategies=['BUSINESS_FIRST','CHAINS_FIRST','INDEPENDENTS_FIRST','GEOGRAPHY','INCOMPLETE_FIRST'];
function ivForm(id,fn){imBind(id,fn);}
async function ivPost(path,body){return api(iv2+path,{...body,operation_id:crypto.randomUUID()});}
function ivCampaignTable(items){return `<section class="panel flush"><table><thead><tr><th>Campaign</th><th>Status</th><th>Business candidates</th><th>Menus / source work</th><th>Cost</th><th>Last activity</th></tr></thead><tbody>${items.map(c=>`<tr><td><a href="#ingestion-v02/campaign/${esc(c.id)}">${esc(c.label)}</a><br>${esc(nice(c.strategy))}</td><td>${badge(c.state)}${c.menu_paused?'<br>Menus paused':''}${c.ai_paused?'<br>AI paused':''}</td><td>${Object.values(c.businesses).reduce((a,b)=>a+b,0)} records<br>${c.physical_businesses_created} physical Businesses created<br>${c.businesses.BLOCKED||0} blocked</td><td>${Object.values(c.menus).reduce((a,b)=>a+b,0)} menu sources<br>${c.source_work.length} nutrition/other sources</td><td>${ivMoney(c.known_spend_microusd)} known<br>${ivMoney(c.reserved_microusd)} reserved</td><td>${esc(dateLabel(c.last_checkpoint||c.updated_at))}</td></tr>`).join('')||'<tr><td colspan="6">No campaigns yet. Create an objective, then add acquired source work.</td></tr>'}</tbody></table></section>`;}
managerPage=async function(){
 const [campaigns,jobs]=await Promise.all([api(iv2+'campaigns'),api(imURL+'jobs')]);
 shell('Ingestion',`<div class="heading"><div><h1>Ingestion</h1><p>Set the objective. Monitor progress, spending and exceptions.</p></div><button id="iv-refresh">Refresh</button></div>
 <div class="cards">${[['Campaigns','Plan initial or expansion work that survives restarts.','campaigns','View Campaigns'],['Source Updates','Upload an acquired FSQ change file, preview and process.','upload','Upload Source Update'],['Brands','Use saved engineering knowledge and supported actions.','brands','Ingest / Update Brand']].map(([title,text,link,action])=>`<section class="card"><h2>${title}</h2><p>${text}</p><a class="button-link" href="#ingestion-v02/${link}">${action}</a></section>`).join('')}</div>
 <h2>Campaigns</h2>${ivCampaignTable(campaigns.items)}
 <section class="panel"><h2>Active Work</h2><p>${esc(jobs.worker.state)} · ${esc(jobs.worker.error||'')}</p>${jobs.items.filter(j=>['QUEUED','RUNNING','BLOCKED_BY_BURP','PAUSED'].includes(j.state)).map(j=>`<p><a href="#ingestion/${esc(j.id)}">${esc(j.label)}</a> ${badge(j.state)} · ${j.processed}/${j.total} source records processed · ${j.blocked} blocked</p>`).join('')||'<p>No active work.</p>'}</section>
 <section class="panel"><h2>Recent Runs</h2>${jobs.items.filter(j=>['COMPLETED','COMPLETED_WITH_ISSUES','FAILED','CANCELED'].includes(j.state)).slice(0,10).map(j=>`<p><a href="#ingestion/${esc(j.id)}">${esc(j.label)}</a> ${badge(j.state)}</p>`).join('')||'<p>No recent finished jobs.</p>'}<a href="#ingestion-v02/history">Historical Runs</a></section>
 <section class="panel"><h2>Advanced</h2><a href="#ingestion-v02/advanced">Targeted Ingestion / Developer Tools</a><p>One restaurant, recovery, raw evidence and technical rules.</p></section><section class="panel"><h2>Settings</h2><a href="#ingestion-v02/automation">Automation Settings</a><p>Coverage, candidate limits, interval and authorized cost.</p></section>`);
 document.querySelector('#iv-refresh').onclick=managerPage;
};
async function ivCampaigns(){
 const d=await api(iv2+'campaigns?'+new URLSearchParams({offset:ivOffset}));shell('Ingestion',`${ivNav()}<div class="heading"><h1>Campaigns</h1>${user.role==='ADMIN'?'<a class="button-link" href="#ingestion-v02/new">New Campaign</a>':''}</div><p>Long-running objectives contain separate acquired-evidence workstreams. ${d.total} campaigns.</p>${ivCampaignTable(d.items)}<p><button id="iv-prev" ${ivOffset===0?'disabled':''}>Previous</button> <button id="iv-next" ${ivOffset+50>=d.total?'disabled':''}>Next</button></p>`);
 document.querySelector('#iv-prev').onclick=()=>{ivOffset=Math.max(0,ivOffset-50);ivCampaigns();};document.querySelector('#iv-next').onclick=()=>{ivOffset+=50;ivCampaigns();};
}
let ivOffset=0;
async function ivNew(){shell('Ingestion',`${ivNav()}<h1>New Campaign</h1><section class="panel"><p>Start with Business establishment. Menus and AI begin paused. Creating a campaign does not acquire source data.</p><form id="iv-new" class="account-form"><label class="stack">Campaign name<input name="label" required maxlength="200" placeholder="Initial U.S. Database — Phase 1"></label><label class="stack">Objective<textarea name="objective" required></textarea></label><label class="stack">Processing strategy<select name="strategy">${opts(ivStrategies,'BUSINESS_FIRST')}</select></label><label class="stack">Focus geography (when prioritizing geography)<input name="focus_geography" placeholder="CO"></label><label class="stack">Authorized total budget, USD<input name="budget" type="number" min="0" step="0.01" value="0" required></label><button class="primary">Create Campaign</button></form></section>`);ivForm('iv-new',async b=>{if(!confirm(`Authorize a campaign ceiling of $${b.budget}? No paid provider is connected.`))return;const d=await ivPost('campaigns',{label:b.label,objective:b.objective,strategy:b.strategy,focus_geography:b.focus_geography,budget_microusd:Math.round(Number(b.budget)*1e6),confirm_budget:true});location.hash='ingestion-v02/campaign/'+d.id;});}
let ivWorkOffset=0,ivWorkQuery='',ivActiveCampaign=null;
async function ivCampaign(id){
 if(ivActiveCampaign!==id){ivWorkOffset=0;ivWorkQuery='';ivActiveCampaign=id;}
 const [c,menu]=await Promise.all([api(iv2+'campaign?'+new URLSearchParams({id,offset:ivWorkOffset,filter:ivWorkQuery})),api(iv2+'menus?'+new URLSearchParams({campaign:id}))]);if(!c)throw Error('Campaign not found');
 const admin=user.role==='ADMIN',count=c.businesses;
 shell('Ingestion',`${ivNav()}<div class="heading"><div><h1>${esc(c.label)}</h1><p>${badge(c.state)} · ${esc(c.objective)}</p></div><button id="iv-refresh">Refresh progress</button></div>
 ${typeof iqExecutorPanel==='function'?iqExecutorPanel(c.executor):''}
 ${ivCards([['Source records',Object.values(count).reduce((a,b)=>a+b,0)],['Physical Businesses created',c.physical_businesses_created],['Queued',count.QUEUED||0],['Established / recognized records',count.DONE||0],['Needs evidence / BURP',count.BLOCKED||0],['Failed',count.FAILED||0]])}
 <section class="panel"><h2>Processing</h2><p>${esc(nice(c.strategy))} · Menu processing ${c.menu_paused?'paused':'enabled'} · AI ${c.ai_paused?'paused':'enabled'}</p><p>${esc(c.worker)}. Last checkpoint: ${esc(dateLabel(c.last_checkpoint))}. Last worker tick: ${esc(dateLabel(c.worker_last_tick))}. ${c.source_records_last_hour} source records completed in the last hour; no future throughput estimate.</p>${admin?['start','pause','resume','cancel','complete'].map(a=>`<button data-iv-control="${a}" ${['CANCELED','COMPLETED'].includes(c.state)?'disabled':''}>${nice(a)}</button>`).join(' '):''}<p>Cancel preserves established data and evidence. Identity blocks affect their own candidates; resolve through the linked workstream.</p></section>
 <section class="panel"><h2>Workstreams</h2><form id="iv-filter" class="filters"><label>Brand / source / geography / state<input name="q" value="${esc(ivWorkQuery)}" placeholder="Filter by Brand, source, geography or state"></label><button>Filter</button></form><div id="iv-workstreams">${c.workstreams.map(w=>`<article data-iv-workstream="${esc([w.brand,w.source,w.geography,w.state,w.label].join(' ').toLowerCase())}"><p><a href="#ingestion/${esc(w.job)}">${esc(w.label)}</a> ${badge(w.state)} · ${w.processed}/${w.total} source records<br>${esc([w.brand,w.geography,w.source].filter(Boolean).join(' · '))}<br>${esc(w.error||'')}<br>Workstream ceiling: ${ivMoney(w.budget_microusd)}</p>${admin?`<button data-iv-work-budget="${esc(w.id)}">Adjust budget</button>`:''}</article>`).join('')||'<p>No acquired source work added yet.</p>'}</div><p>${c.workstream_total} workstreams · <button id="iv-work-prev" ${ivWorkOffset===0?'disabled':''}>Previous</button> <button id="iv-work-next" ${c.workstreams.length<50?'disabled':''}>Next</button></p>${admin?`<a href="#ingestion-v02/work/${esc(id)}">Add acquired Business work</a>`:''}</section>
 <section class="panel"><h2>Menu evaluation / processing</h2><p>Business establishment continues independently. Each source is evaluated before paid processing. ${c.executor?'The scheduled executor processes supported factual menus; local availability and prices retain exact Store context.':'No source executor is configured for this campaign.'}</p>${ivCards(Object.entries(c.menus).map(([k,v])=>[nice(k),v]))}<p>Showing ${menu.items.length} of ${menu.total??menu.items.length} source results.</p>${menu.items.map(m=>`<article class="audit-entry"><strong>${esc(m.source_url)}</strong> ${badge(m.state)}<p>${esc(m.decision||'Awaiting evaluation')}<br>Business: ${esc(m.business)} · Configuration: ${esc(m.configuration||'Unknown')} · Expected cost: ${ivMoney(m.expected_cost_microusd)}</p>${admin&&m.state==='NOT_EVALUATED'?`<button data-iv-evaluate="${esc(m.id)}">Evaluate source</button>`:''}</article>`).join('')||'<p>No menu sources discovered in this campaign.</p>'}</section>
 <section class="panel"><h2>Nutrition / Allergen / Ingredient sources</h2><p>Sources preserve distinct kinds and the existing ItemFactProfile contract. Exact Item, variant, serving and provenance are required. ${c.executor?'Factual sources use the scheduled canonical processor. Retained records and unavailable sources remain distinguishable.':'No source executor is configured for this campaign.'}</p>${c.source_work.map(s=>`<p>${esc(s.kind)} · ${badge(s.state)}${s.resources?' · '+esc(s.resources)+' resources':''} · ${esc(s.source_reference)}</p>`).join('')||'<p>No source work registered. Counts of Items with these facts are unavailable.</p>'}</section>
 <section class="panel"><h2>Budget / Cost</h2>${ivCards([['Authorized ceiling',ivMoney(c.budget_microusd)],['Known receipt spend',ivMoney(c.known_spend_microusd)],['Reserved',ivMoney(c.reserved_microusd)],['Projected remaining spend','Unavailable']])}<p>${esc(c.billing_coverage)}</p>${admin?`<form id="iv-policy" data-version="${c.version}" class="account-form"><label class="stack">Campaign ceiling, USD<input name="budget" required type="number" min="0" step="0.01" value="${c.budget_microusd/1e6}"></label><label class="stack">Menu ceiling, USD<input name="menu_budget" required type="number" min="0" step="0.01" value="${c.menu_budget_microusd/1e6}"></label><label class="stack">AI reasoning ceiling, USD<input name="ai_budget" required type="number" min="0" step="0.01" value="${c.reasoning_budget_microusd/1e6}"></label><label class="stack">Menus<select name="menu_paused"><option value="true" ${c.menu_paused?'selected':''}>Paused — continue Businesses</option><option value="false" ${!c.menu_paused?'selected':''}>Enabled when executor exists</option></select></label><label class="stack">AI assistance<select name="ai_paused"><option value="true" ${c.ai_paused?'selected':''}>Paused — continue deterministic work</option><option value="false" ${!c.ai_paused?'selected':''}>Enabled within budget when provider exists</option></select></label><label class="stack">Strategy<select name="strategy">${opts(ivStrategies,c.strategy)}</select></label><label class="stack">Focus geography<input name="focus_geography" value="${esc(c.focus_geography)}"></label><label class="stack">Processing priority (0–100)<input name="priority" required type="number" min="0" max="100" value="${c.priority}"></label><label class="stack">Authorization reason<textarea name="reason" required></textarea></label><button>Approve policy and budget</button></form>`:''}</section>
 <section class="panel"><h2>BURP exceptions</h2>${ivCards(['CRITICAL','HIGH','NORMAL','LOW'].map(k=>[k,c.burps[k]||0]))}<a href="#Cases">Open BURP Queue</a></section><details class="panel"><summary>Operator audit</summary>${(c.audit||[]).map(a=>`<p>${esc(a.action)} · ${esc(a.actor||a.actor_id)} · ${esc(dateLabel(a.at))}</p>`).join('')}</details>`);
 if(c.executor&&typeof iqBindExecutor==='function')iqBindExecutor(c.executor,()=>ivCampaign(id));
 document.querySelector('#iv-refresh').onclick=()=>ivCampaign(id);
 ivForm('iv-filter',async b=>{ivWorkQuery=b.q;ivWorkOffset=0;await ivCampaign(id);});
 document.querySelector('#iv-work-prev').onclick=()=>{ivWorkOffset=Math.max(0,ivWorkOffset-50);ivCampaign(id);};document.querySelector('#iv-work-next').onclick=()=>{ivWorkOffset+=50;ivCampaign(id);};
 document.querySelectorAll('[data-iv-control]').forEach(b=>b.onclick=async()=>{const reason=prompt('Reason for '+b.dataset.ivControl);if(!reason)return;try{await ivPost('campaign-control',{id,version:c.version,action:b.dataset.ivControl,reason});await ivCampaign(id);}catch(e){toast(e.message);}});
 document.querySelectorAll('[data-iv-work-budget]').forEach(b=>b.onclick=async()=>{const value=prompt('New workstream ceiling, USD');if(value===null)return;const budget=Number(value);if(!Number.isFinite(budget)||budget<0){toast('Enter a valid nonnegative amount');return;}const reason=prompt('Spending authorization reason');if(!reason||!confirm('Authorize this workstream ceiling of $'+budget+'?'))return;try{await ivPost('workstream-budget',{id:b.dataset.ivWorkBudget,budget_microusd:Math.round(budget*1e6),confirm_budget:true,reason});await ivCampaign(id);}catch(e){toast(e.message);}});
 document.querySelectorAll('[data-iv-evaluate]').forEach(b=>b.onclick=async()=>{try{await ivPost('menu-evaluate',{id:b.dataset.ivEvaluate});await ivCampaign(id);}catch(e){toast(e.message);}});
 ivForm('iv-policy',async b=>{if(!confirm('Approve these spending ceilings and processing controls?'))return;await ivPost('campaign-control',{id,version:c.version,action:'policy',budget_microusd:Math.round(Number(b.budget)*1e6),menu_budget_microusd:Math.round(Number(b.menu_budget)*1e6),reasoning_budget_microusd:Math.round(Number(b.ai_budget)*1e6),menu_paused:b.menu_paused==='true',ai_paused:b.ai_paused==='true',strategy:b.strategy,focus_geography:b.focus_geography,priority:Number(b.priority),confirm_budget:true,reason:b.reason});if(location.hash==='#ingestion-v02/campaign/'+id)await ivCampaign(id);});
}
async function ivUpload(){
 shell('Ingestion',`${ivNav()}<h1>Upload Source Update</h1><section class="panel"><p>Select an acquired FSQ delta file (native fields or normalized acquired records). JSON arrays and NDJSON are supported, up to 100 events / 180 KB per file. Portal, Iceberg, Parquet, CSV and ZIP require engineering adapters.</p><label class="stack">Source file<input id="iv-file" type="file" accept=".json,.jsonl,.ndjson"></label><p id="iv-file-error" role="status"></p><div id="iv-preview"></div></section><section class="panel"><h2>Staged source updates</h2><div id="iv-releases"></div></section>`);
 const d=await api(imURL+'jobs');document.querySelector('#iv-releases').innerHTML=d.releases.map(r=>`<p><a href="#source-release/${encodeURIComponent(r.id)}">${esc(r.id)}</a> ${badge(r.state)} ${user.role==='ADMIN'&&r.state==='STAGED'?`<button data-iv-process="${esc(r.id)}">Process update</button>`:''}</p>`).join('')||'<p>No updates staged.</p>';
 document.querySelectorAll('[data-iv-process]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await api(imURL+'process-release',{release_id:b.dataset.ivProcess});location.hash=r.id?'ingestion/'+r.id:'source-release/'+encodeURIComponent(b.dataset.ivProcess);}catch(e){toast(e.message);b.disabled=false;}});
 document.querySelector('#iv-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;const preview=document.querySelector('#iv-preview');preview.innerHTML='';try{
  if(file.size>180000)throw Error('Split this file into source files under 180 KB / 100 events.');
  const body={filename:file.name,format:/\.json$/i.test(file.name)?'JSON':'NDJSON',content:await file.text()};const p=await ivPost('file-preview',body);
  preview.innerHTML=`<h2>File preview · ${esc(file.name)}</h2>${ivCards([...Object.entries(p.actions).map(([k,v])=>[nice(k),v]),['Invalid records',p.invalid_records.length],['Needs acquired Place details',p.requires_acquisition],['Mapped source records',p.known_source_records],['Potential new source candidates',p.unmapped_source_records]])}<p>Source records are not physical Business counts. Removes/merges enter lifecycle review; they never close or merge canonical Businesses automatically.</p><p>Processing uses Automation Settings for new-candidate coverage/authorization; unmapped records may remain awaiting authorization.</p>${p.invalid_records.map(r=>`<p>Row ${r.row}: ${esc(r.reason)}</p>`).join('')}<label class="stack">Provider release/version (optional)<input id="iv-release-version" value="${esc(p.release_id)}"></label><button id="iv-stage" ${p.invalid_records.length?'disabled':''}>Stage validated update</button>`;
  document.querySelector('#iv-stage').onclick=async()=>{try{const r=await ivPost('file-stage',{...body,release_id:document.querySelector('#iv-release-version').value||undefined});location.hash='source-release/'+encodeURIComponent(r.id);}catch(error){toast(error.message);}};
 }catch(error){document.querySelector('#iv-file-error').textContent=error.message;}};
}
async function ivBrands(key){
 const d=await api(iv2+'profiles');const p=d.items.find(p=>p.key===key);
 if(!p){shell('Ingestion',`${ivNav()}<h1>Ingest / Update Brand</h1><p>Saved profiles distinguish historical adapter knowledge from executable manager actions.</p><div class="cards">${d.items.map(p=>`<section class="card"><h2>${esc(p.display_name)}</h2><p>${p.enabled?'Enabled':'Not activated'} · Profile v${p.version}</p>${p.capabilities.map(c=>`<p>${esc(nice(c.capability))}: ${esc(nice(c.status))}</p>`).join('')}<a href="#ingestion-v02/brand/${esc(p.key)}">Open Brand Profile</a></section>`).join('')}</div><section class="panel"><h2>Other Brands</h2><p>Needs Engineering. Establish source ownership, adapter, focused tests and an approved profile before normal operations.</p></section>`);return;}
 shell('Ingestion',`${ivNav()}<h1>${esc(p.display_name)}</h1><p>Brand Ingestion Profile · v${p.version} · ${p.enabled?'Enabled':'Not activated'} · Last successful manager ingestion: ${esc(dateLabel(p.last_success))}</p><section class="panel"><h2>Capabilities</h2>${p.capabilities.map(c=>`<article class="audit-entry"><strong>${esc(nice(c.capability))}</strong> ${badge(c.status)}<p>${esc(c.detail)}</p></article>`).join('')}<p>Items with nutrition / allergens / ingredients: <strong>${p.item_counts?`${p.item_counts.items} Items · ${p.item_counts.nutrition} nutrition · ${p.item_counts.allergens} allergens · ${p.item_counts.ingredients} ingredients`:'Unavailable'}</strong>.</p></section><section class="panel"><h2>Supported actions</h2>${p.enabled&&p.brand?`<a class="button-link" href="#ingestion-v02/brand-work/${esc(p.key)}">Process acquired Businesses</a>`:'<p>Activate and bind to the exact canonical Brand before starting a Brand run.</p>'}${p.source_plan&&p.enabled&&user.role==='ADMIN'?'<button id="iv-discover">Create source acquisition campaign</button><p>Discovery runs durably from the configured public source plan. The full universe remains held until bounded preflight validation passes.</p>':'<p>Source acquisition requires an enabled, validated engineering profile.</p>'}</section><section class="panel"><h2>Menu learning</h2>${p.learning?`${ivCards([['Locations discovered',p.learning.locations_discovered],['Location checkpoints',p.learning.location_checkpoints],['Store menu roots processed',p.learning.menu_root_checkpoints],['Category resources processed',p.learning.category_checkpoints],['Observed listing configurations',p.learning.configurations],['New product definition probes',p.learning.definition_probes]])}<a href="#ingestion-queue/run/${esc(p.learning.run)}">View current acquisition run</a><p>Store roots retain observed product/availability context. Equivalent configurations reuse definitions; new configurations and unresolved product codes receive representative category inspection. Local prices require their own source observation.</p>`:'<p>No current source execution is recorded for this profile.</p>'}</section>${user.role==='ADMIN'?`<section class="panel"><h2>Profile activation</h2><form id="iv-profile"><label class="stack">Exact canonical Brand<select name="brand" required><option value="">Select evidenced identity</option>${ivBrandOptions(p.brand)}</select></label><label class="stack">Profile<select name="enabled"><option value="true" ${p.enabled?'selected':''}>Enabled</option><option value="false" ${!p.enabled?'selected':''}>Disabled</option></select></label><label class="stack">Identity / activation reason<textarea name="reason" required></textarea></label><button>Save profile activation</button></form></section>`:''}<details class="panel"><summary>Engineering Details</summary><p>${esc(p.limitations)}</p><p>Adapter: ${esc(p.adapter)} · Evidence: ${esc(p.evidence_artifact)}</p>${p.sources.map(s=>`<p>${esc(s.kind)} · ${esc(s.reference)}<br>${esc(s.provenance)}</p>`).join('')}${p.rules.map(r=>`<p>${esc(r.category)} / ${esc(r.name)}: ${esc(r.value)}</p>`).join('')}</details>`);
 document.querySelector('#iv-discover')?.addEventListener('click',async()=>{try{const d=await api('/api/ingestion/executor/create',{profile:p.key,label:p.display_name+' — public source discovery — '+new Date().toISOString(),operation_id:crypto.randomUUID()});location.hash='ingestion-queue/run/'+d.run;}catch(e){toast(e.message);}});
 ivForm('iv-profile',async b=>{await ivPost('profile-control',{key:p.key,brand:b.brand,enabled:b.enabled==='true',reason:b.reason});await ivBrands(key);});
}
async function ivWork(campaign,profileKey){
 const profiles=await api(iv2+'profiles'),p=profiles.items.find(p=>p.key===profileKey);const campaigns=await api(iv2+'campaigns');
 shell('Ingestion',`${ivNav()}<h1>${p?'Update '+esc(p.display_name):'Add acquired Business work'}</h1><section class="panel"><p>Import already acquired normalized records. No network acquisition runs inside the canonical transaction. Select a bulk file once. Intake saves a server cursor; reselect the same file after interruption to resume. Bounded jobs are created automatically.</p><form id="iv-work"><label class="stack">Campaign<select name="campaign" required>${campaigns.items.filter(c=>!['CANCELED','COMPLETED'].includes(c.state)).map(c=>`<option value="${esc(c.id)}" ${campaign===c.id?'selected':''}>${esc(c.label)}</option>`).join('')}</select></label><label class="stack">Workstream name<input name="label" required value="${esc(p?p.display_name+' acquired update':'Acquired Business evidence')}"></label><label class="stack">Brand<select name="brand_id"><option value="">Identity needs review</option>${ivBrandOptions(p?.brand)}</select></label><label class="stack">Source<select name="provider"><option>FIRST_PARTY</option><option>FSQ</option><option>OWNER_SUBMISSION</option><option>USER_REPORT</option></select></label><label class="stack">Workstream scope (scheduling only)<select name="classification"><option value="UNSPECIFIED">Mixed / unspecified</option><option value="CHAIN">Chain locations</option><option value="INDEPENDENT">Independent Businesses</option></select></label><label class="stack">Geography<input name="geography" placeholder="Utah / Salt Lake City"></label><label class="stack">Acquired Business file (normalized JSON array or NDJSON, up to 32 MB)<input id="iv-work-file" type="file" accept=".json,.jsonl,.ndjson" required></label><label class="stack">Authorized workstream ceiling, USD<input name="budget" type="number" min="0" step="0.01" value="0" required></label><button>Queue Business work</button><p id="iv-import-status" role="status"></p></form><p>No campaign yet? <a href="#ingestion-v02/new">Create Campaign</a>.</p></section>`);
 ivForm('iv-work',async b=>{
  const file=document.querySelector('#iv-work-file').files[0];if(file.size>32*1024*1024)throw Error('Maximum 32 MB per bulk acquired file; engineering feeders may append further work');
  const content=await file.text(),records=/\.json$/i.test(file.name)?JSON.parse(content):content.split(/\r?\n/).filter(x=>x.trim()).map(x=>JSON.parse(x));
  if(!Array.isArray(records)||!records.length||records.length>1000000)throw Error('A nonempty acquired-record array or NDJSON file is required');
  const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(content)),sha256=[...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('');
  const progress=await api(iv2+'import-progress?'+new URLSearchParams({campaign:b.campaign,sha256}));
  if(!confirm('Queue '+records.length+' source records with a per-workstream ceiling of $'+b.budget+'? The campaign ceiling also applies.'))return;
  let offset=progress?.completed_records||0;const status=document.querySelector('#iv-import-status');
  while(offset<records.length){
   const batch=records.slice(offset,offset+100);
   if(new TextEncoder().encode(JSON.stringify(batch)).length>220000)throw Error('One acquired chunk is too large; engineering must reduce source record size. Completed chunks remain saved.');
   status.textContent='Saving acquired records '+(offset+1)+'–'+(offset+batch.length)+' of '+records.length+'…';
   await ivPost('import-work',{campaign:b.campaign,label:b.label,brand_id:b.brand_id||null,provider:b.provider,geography:b.geography,classification:b.classification,records:batch,budget_microusd:Math.round(Number(b.budget)*1e6),confirm_budget:true,...(p?{profile:p.key}:{}),sha256,filename:file.name,total_records:records.length,ordinal:offset});offset+=batch.length;
  }
  status.textContent='All source records queued. Business establishment uses the saved candidate checkpoints.';location.hash='ingestion-v02/campaign/'+b.campaign;
 });
}
async function ivLegacy(mode){
 if(mode==='history'){const r=await api('/api/runs');const historical=r.items.filter(x=>!/^[-a-f0-9]{36}$/i.test(x.run_id));shell('Ingestion',ivNav()+'<h1>Historical Runs</h1><p>Historical LAB script artifacts remain separate. No resumable campaign checkpoints have been fabricated or migrated.</p>'+(historical.length?runTable(historical):'<section class="panel">No historical script runs imported into hosted development. Recent manager jobs remain under Recent Runs.</section>'));return;}
 await ingestionV01Page();const content=document.querySelector('.content');content.insertAdjacentHTML('afterbegin',ivNav());

 // Retain original bound forms, validators and callbacks; show only the selected technical workspace.
 for(const el of [...content.children]){if(el.tagName==='A')continue;const keep=mode==='automation'?el.querySelector?.('#im-settings'):el.querySelector?.('#im-create')||el.querySelector?.('#im-rule')||el.querySelector?.('#im-release');if(!keep)el.hidden=true;}
 const title=document.createElement('h1');title.textContent=mode==='automation'?'Automation Settings':'Advanced / Targeted Ingestion';content.insertBefore(title,content.children[1]);
 if(mode==='automation'){const form=document.querySelector('#im-settings');form.closest('section').querySelector('h2').textContent='Automatically process newly staged source updates';form.closest('section').querySelector('p').textContent='On/Off, geographic coverage, candidate and cost limits, and processing interval. This processes staged files, not the FSQ Portal.';}
}
route=async function(){const raw=decodeURIComponent(location.hash.slice(1));if(!raw.startsWith('ingestion-v02/'))return ingestionV01Route();try{const parts=raw.split('/'),view=parts[1],id=parts.slice(2).join('/');if(view==='campaigns')return await ivCampaigns();if(view==='new')return await ivNew();if(view==='campaign')return await ivCampaign(id);if(view==='upload')return await ivUpload();if(view==='brands'||view==='brand')return await ivBrands(id);if(view==='work')return await ivWork(id);if(view==='brand-work')return await ivWork(null,id);if(['advanced','automation','history'].includes(view))return await ivLegacy(view);throw Error('Unknown ingestion workspace');}catch(error){showError(error);}};
const ivOriginalRelease=managerRelease;
managerRelease=async function(id){await ivOriginalRelease(id);const release=await api(imURL+'release?'+new URLSearchParams({id}));if(user.role==='ADMIN'&&release.state==='STAGED'){const panel=document.createElement('section');panel.className='panel';panel.innerHTML='<h2>Process source update</h2><p>New candidates follow the coverage, candidate and budget limits in Automation Settings. Known changes enter review. Removes and merges remain evidence.</p><button id="iv-process-release">Process validated update</button><p><a href="#ingestion-v02/automation">Review Automation Settings</a></p>';document.querySelector('.content').append(panel);document.querySelector('#iv-process-release').onclick=async()=>{try{const r=await api(imURL+'process-release',{release_id:id});if(r.id)location.hash='ingestion/'+r.id;else await managerRelease(id);}catch(e){toast(e.message);}};}};
window.removeEventListener('hashchange',ingestionV01Route);
window.addEventListener('hashchange',route);

/* Run/candidate operator surface; legacy campaign tools remain under Advanced. */
const iqURL='/api/ingestion/queue/';
const iqPost=(path,body)=>api(iqURL+path,{...body,operation_id:crypto.randomUUID()});
async function* iqNativeRows(file){
 const reader=file.stream().pipeThrough(new TextDecoderStream()).getReader();let pending='';
 try{while(true){const {done,value}=await reader.read();if(done)break;pending+=value;let newline;while((newline=pending.indexOf('\n'))>=0){const line=pending.slice(0,newline).trim();pending=pending.slice(newline+1);if(line)yield JSON.parse(line);}if(pending.length>1000000)throw Error('Native source row exceeds 1 MB');}if(pending.trim())yield JSON.parse(pending);}finally{reader.releaseLock();}
}
const iqReference=f=>[f.name,f.size,f.lastModified].join(':');
async function iqChunkRows(records,save){let batch=[],ordinal=0;for await(const row of records){batch.push(row);if(batch.length===50){await save(batch,ordinal++);batch=[];}}if(batch.length)await save(batch,ordinal);}
function iqExecutorPanel(e){
 if(!e)return '';
 const rows=e.source_counts||[],sum=(kind,states)=>rows.filter(r=>(!kind||r.kind===kind)&&(!states||states.includes(r.state))).reduce((n,r)=>n+Number(r.n),0);
 return `<section class="panel"><h2>Source acquisition</h2><p>${esc(nice(e.phase))} · ${esc(e.full_scope)} · Last worker checkpoint: ${esc(dateLabel(e.worker_tick))}</p>${ivCards([['Locations discovered',e.discovered_locations],['Locations processed',sum('LOCATION',['DONE','SKIPPED'])],['Location review',sum('LOCATION',['REVIEW','UNAVAILABLE'])],['Locations pending',sum('LOCATION',['QUEUED','RETRY','LEASED','ACQUIRED','WAITING'])],['Physical Businesses',e.physical_businesses],['Menus processed',sum('MENU_ROOT',['DONE'])+sum('MENU_CATEGORY',['DONE'])],['Acquisition attempts',e.requests?.count||0],['AI tokens',e.ai_tokens]])}<p>Network requests and canonical writes run as separate saved checkpoints. Routine Verification remains separate from BURP intervention. Source restrictions retain an explicit unavailable outcome.</p><a href="#ingestion-v02/campaign/${esc(e.campaign)}">Open acquisition campaign</a>${user.role==='ADMIN'&&e.phase==='DISCOVERY'?'<button data-executor-action="preflight">Start bounded preflight</button>':''}${user.role==='ADMIN'&&e.phase==='PREFLIGHT'?'<button data-executor-action="validate">Validate preflight</button><button data-executor-action="release">Release validated full universe</button>':''}<details><summary>Source progress and accounting</summary><table><thead><tr><th>Source</th><th>State</th><th>Resources</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(nice(r.kind))}</td><td>${esc(nice(r.state))}</td><td>${esc(r.n)}</td></tr>`).join('')}</tbody></table><p>Transferred bytes: ${esc(e.requests?.bytes||0)} · Canonical server milliseconds: ${esc(Math.round(e.canonical_ms||0))}. Total infrastructure cost: unavailable.</p></details></section>`;
}
function iqBindExecutor(e,reload){
 for(const button of document.querySelectorAll('[data-executor-action]'))button.onclick=async()=>{try{const result=await api('/api/ingestion/executor/'+button.dataset.executorAction,{run:e.run.id,operation_id:crypto.randomUUID()});toast(result.passed===false?'Preflight needs attention':result.passed?'Preflight passed':'Checkpoint saved');await reload();}catch(error){toast(error.message);}};
}
async function iqHome(id){
 const runs=await api(iqURL+'runs');const chosen=id||runs.items.find(r=>r.state!=='COMPLETED')?.id||runs.items[0]?.id;
 const run=chosen?await api(iqURL+'run?'+new URLSearchParams({id:chosen})):null;
 const executor=run?.source?.profile?await api('/api/ingestion/executor/run?'+new URLSearchParams({id:chosen})):null;
 const counts=run?.counts||{},total=Object.values(counts).reduce((a,b)=>a+b,0);
 shell('Ingestion',`<div class="heading"><div><h1>Ingestion</h1><p>Brand source acquisition, Initial U.S. Ingestion and periodic FSQ updates</p></div><button id="iq-refresh">Refresh</button></div>
 <p><a href="#ingestion-queue/import/INITIAL_US">Build Initial U.S. Queue</a> · <a href="#ingestion-queue/import/FSQ_UPDATE">Process FSQ Update</a> · <a href="#ingestion-v02/brands">Brand readiness</a></p>
 ${iqExecutorPanel(executor)}
 ${run?`<section class="panel"><h2>${run.kind==='INITIAL_US'?'Initial U.S. Ingestion':'FSQ Update'}</h2><p>${esc(run.release)} · ${badge(run.state)}</p>${ivCards([['Candidates',total],['Processed',counts.DONE||0],['Queued',counts.QUEUED||0],['Processing',counts.LEASED||0],['Waiting on incidents',counts.WAITING||0],['Data review',counts.REVIEW||0],['BURPs',run.burps],['Known spend',ivMoney(run.known_spend_microusd)]])}
 ${user.role==='ADMIN'&&['READY','PAUSED','RUNNING'].includes(run.state)?`<button id="iq-control">${run.state==='RUNNING'?'Pause':'Start / Resume'}</button>`:''}<p>Saved workers continue when this browser closes. Unknown spend remains unavailable.</p></section>
 <section class="panel"><h2>Currently Processing</h2>${executor?'<p>Current source progress is shown above. Candidate counts describe destinations that have reached canonical processing.</p>':run.groups.map(g=>`<p>${esc(g.grouping.replace(/^brand:/,''))}: ${g.processed}/${g.locations} processed</p>`).join('')||'<p>No groups queued.</p>'}</section>
 <section class="panel"><h2>Needs Attention</h2>${run.incidents.map(i=>`<article><h3>${esc(i.scope)}</h3><p>${esc(nice(i.signature))} · ${i.waiting} waiting · ${i.state==='FIX_AVAILABLE'?'Fix validated':'Needs engineering'}</p>${i.state==='FIX_AVAILABLE'&&user.role==='ADMIN'?`<button data-iq-resume="${esc(i.id)}">Resume affected candidates</button>`:''}</article>`).join('')||'<p>No systemic incidents.</p>'}</section>
 <details class="panel"><summary>Source and queue details</summary><p>Excluded non-target places: ${run.import.excluded}; invalid/unusable: ${run.import.invalid}; duplicate rows: ${run.import.duplicates}. Known Brand candidates: ${run.known_brand_candidates}; known Brands: ${run.known_brands}.</p><p>Largest established Brands first, then high-leverage suspected groups, smaller Brands and independents. Suspected groups do not authorize shared Brand enrichment.</p><pre>${esc(JSON.stringify(run.source,null,2))}</pre></details>`:'<section class="panel">No source universe has been imported. Building a queue does not create canonical Businesses.</section>'}
 <section class="panel"><h2>Recent Runs</h2>${runs.items.map(r=>`<p><a href="#ingestion-queue/run/${esc(r.id)}">${r.kind==='INITIAL_US'?'Initial U.S. Ingestion':'FSQ Update'} · ${esc(r.release)}</a> ${badge(r.state)}</p>`).join('')||'<p>No runs.</p>'}</section>
 <details class="panel"><summary>Advanced / Technical Details</summary><p><a href="#ingestion-v02/campaigns">Previous campaign records</a> · <a href="#ingestion-v02/advanced">Targeted tools</a> · <a href="#ingestion-v02/automation">Previous staged-file settings</a></p><p>Parquet and authenticated Iceberg source import use the engineering feeder. Brand rules, adapters, memory promotion and incident fix validation remain engineering operations.</p></details>`);
 iqBindExecutor(executor,()=>iqHome(chosen));
 document.querySelector('#iq-refresh').onclick=()=>iqHome(chosen);
 document.querySelector('#iq-control')?.addEventListener('click',async()=>{try{await iqPost(run.state==='RUNNING'?'pause':'start',{run:run.id});await iqHome(run.id);}catch(e){toast(e.message);}});
 for(const button of document.querySelectorAll('[data-iq-resume]'))button.onclick=async()=>{try{await iqPost('resume-incident',{id:button.dataset.iqResume});await iqHome(run.id);}catch(e){toast(e.message);}};
}
async function iqImport(kind){
 shell('Ingestion',`<a href="#Ingestion">Ingestion</a><h1>${kind==='INITIAL_US'?'Build Initial U.S. Queue':'Process FSQ Update'}</h1><section class="panel"><p>Select native FSQ source files once. No manually transformed candidates are required. This browser imports NDJSON/JSONL; the engineering feeder also streams Parquet and the authenticated Iceberg catalog.</p><form id="iq-import" class="account-form"><label class="stack">FSQ release / export version<input name="release" required maxlength="200"></label><label class="stack">Native Categories file<input id="iq-categories" type="file" accept=".ndjson,.jsonl" required></label><label class="stack">Native U.S. Places files<input id="iq-places" type="file" accept=".ndjson,.jsonl" multiple required></label>${kind==='FSQ_UPDATE'?'<label class="stack">Native Delta files<input id="iq-deltas" type="file" accept=".ndjson,.jsonl" multiple required></label>':''}<button>Import source and prepare queue</button><p id="iq-status" role="status"></p></form><p>After an interruption, reselect the same files and release. Saved chunks are replay-safe. Processing begins only after queue preparation and Start / Resume.</p></section>`);
 ivForm('iq-import',async values=>{
  const category=document.querySelector('#iq-categories').files[0],places=[...document.querySelector('#iq-places').files],deltas=kind==='FSQ_UPDATE'?[...document.querySelector('#iq-deltas').files]:[];
  const status=document.querySelector('#iq-status');
  const source={catalog:'FSQ OS native export',files:[category,...places,...deltas].map(f=>({name:f.name,size:f.size,last_modified:f.lastModified}))};
  const {id:run}=await iqPost('create',{kind,release:values.release,source});status.textContent='Importing source into saved run '+run;
  const existing=await api(iqURL+'run?'+new URLSearchParams({id:run}));if(existing.state!=='IMPORTING'){location.hash='ingestion-queue/run/'+run;return;}
  await iqChunkRows(iqNativeRows(category),records=>iqPost('categories',{run,records}));
  const save=(file)=>(records,ordinal)=>{status.textContent='Saving '+file.name+' · chunk '+ordinal;return iqPost('import',{run,reference:iqReference(file)+':'+ordinal,records});};
  if(kind==='INITIAL_US'){
   for(const file of places)await iqChunkRows(iqNativeRows(file),save(file));
  }else{
   // Disk-backed native Places lookup for Delta hydration; never enumerate the population in UI.
   const name='incredible-fsq-hydration-'+crypto.randomUUID();
   const db=await new Promise((resolve,reject)=>{const req=indexedDB.open(name,1);req.onupgradeneeded=()=>req.result.createObjectStore('places',{keyPath:'fsq_place_id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
   try{
    for(const file of places)await iqChunkRows(iqNativeRows(file),records=>new Promise((resolve,reject)=>{const tx=db.transaction('places','readwrite');for(const row of records)tx.objectStore('places').put(row);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);}));
    for(const file of deltas){
     async function* hydrated(){for await(const event of iqNativeRows(file)){if(['add','update'].includes(event.action)){const row=await new Promise((resolve,reject)=>{const req=db.transaction('places').objectStore('places').get(event.fsq_place_id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});if(!row)throw Error('Delta needs matching native Places row: '+event.fsq_place_id);yield {...row,action:event.action};}else yield event;}}
     await iqChunkRows(hydrated(),save(file));
    }
   }finally{db.close();indexedDB.deleteDatabase(name);}
  }
  await iqPost('finalize',{run});location.hash='ingestion-queue/run/'+run;
 });
}
const iqPreviousRoute=route;
managerPage=()=>iqHome();
route=async function(){const raw=decodeURIComponent(location.hash.slice(1));if(!raw.startsWith('ingestion-queue/'))return iqPreviousRoute();try{const [,view,id]=raw.split('/');if(view==='run')return await iqHome(id);if(view==='import'&&['INITIAL_US','FSQ_UPDATE'].includes(id))return await iqImport(id);throw Error('Unknown ingestion page');}catch(e){showError(e);}};
window.removeEventListener('hashchange',iqPreviousRoute);
window.addEventListener('hashchange',route);
const iqBrandDiagnostics=ivBrands;
ivBrands=async function(id){await iqBrandDiagnostics(id);const form=document.querySelector('#iv-profile');if(form){const section=form.closest('section'),details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Engineering profile activation';details.className='panel';section.before(details);details.append(summary,section);}};
